Canvas { context, size in
    let rect = CGRect(origin: .zero, size: size)
    context.addFilter(.blur(radius: 2))
    context.fill(Path(ellipseIn: rect), with: .color(.blue))
    context.stroke(
        Path(rect),
        with: .linearGradient(
            Gradient(colors: [.red, .yellow]),
            startPoint: .zero,
            endPoint: CGPoint(x: size.width, y: 0)
        )
    )
}

