renderer.render { size, drawInContext in
    var box = CGRect(origin: .zero, size: size)
    guard let pdf = CGContext(url as CFURL, mediaBox: &box, nil) else { return }
    pdf.beginPDFPage(nil)
    drawInContext(pdf)
    pdf.endPDFPage()
    pdf.closePDF()
}

